out={};err=[]
for vid,s in src.items():
    P,N,Q,A,rl=T[vid]
    pt=[p['text'] for p in s['phrases']]
    assert len(P)==len(pt) and len(N)==len(s['nouns']),vid
    R=[]
    for i,r in enumerate(s['recall']):
        if r in pt: R.append(P[pt.index(r)])
        elif r in s['nouns']: R.append(N[s['nouns'].index(r)])
        elif i==len(s['recall'])-1: R.append(rl)
        else: err.append((vid,r))
    out[vid]={"phrases":P,"nouns":N,"question":Q,"answer":A,"captions":{},"recall":R}
assert not err,err
assert set(T)==set(src)
json.dump(out,open(f'{H}/tr/b001/de/cz.json','w'),ensure_ascii=False,indent=1)
